.calculator {
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-top: 50px;
}

#display {
    width: 200px;
    height: 40px;
    font-size: 24px;
    text-align: right;
    padding: 10px;
    border: 1px solid #ccc;
}

button {
    width: 50px;
    height: 50px;
    margin: 5px;
    font-size: 24px;
    cursor: pointer;
}

let display = document.getElementById('display');
let currentInput = '';
let operator = null;
let firstOperand = null;

function append(number) {
    currentInput += number;
    display.value = currentInput;
}

function calculate(op) {
    if (firstOperand === null) {
        firstOperand = parseFloat(currentInput);
    } else {
        let result = 0;
        switch (operator) {
            case '+':
                result = firstOperand + parseFloat(currentInput);
                break;
            case '-':
                result = firstOperand - parseFloat(currentInput);
                break;
            case '*':
                result = firstOperand * parseFloat(currentInput);
                break;
            case '/':
                result = firstOperand / parseFloat(currentInput);
                break;
        }
        display.value = result;
        currentInput = '';
        operator = op;
        firstOperand = result;
    }
}

function clearDisplay() {
    currentInput = '';
    operator = null;
    firstOperand = null;
    display.value = '0';
}

